#pragma once

#include <vector>
#include <string>
#include <fstream>
#include <stdexcept>

// Generic file-backed storage for a collection of objects.
//
// This is a class template: Repository<Curs>, Repository<Inscriere> and
// Repository<Utilizator> are three distinct classes generated by the compiler
// from this single definition. The repository itself knows nothing about what
// it stores — it only requires T to provide two functions:
//
//   static T deserialize(std::istream&)  — read one object from a stream
//   void     serialize(std::ostream&)    — write one object to a stream
//
// This way the file-handling logic is written once, and each model class
// decides its own on-disk format.
template <typename T>
class Repository {
private:
    std::string filepath;  // path to the data file this repository manages
public:
    // Binds this repository to one data file. No I/O happens here —
    // the file is opened only when loadAll/saveAll are called.
    explicit Repository(const std::string& filepath) : filepath(filepath) {}

    // Reads every object from the file and returns them as a vector.
    // Throws std::runtime_error if the file cannot be opened.
    std::vector<T> loadAll() const {
        std::ifstream file(filepath);
        if (!file.is_open())
            throw std::runtime_error("Nu s-a putut deschide fisierul: " + filepath);

        // There is no record count stored in the file, so we read until EOF.
        // "file >> std::ws" skips whitespace (including the newline left over
        // from the previous record) before checking eof() — without it, a
        // trailing newline at the end of the file would look like one more
        // record and we would deserialize a garbage object.
        std::vector<T> items;
        while (file >> std::ws, !file.eof())
            items.push_back(T::deserialize(file));

        return items;
    }

    // Writes every object to the file, replacing its previous content
    // (ofstream truncates the file on open by default).
    // Throws std::runtime_error if the file cannot be opened for writing.
    void saveAll(const std::vector<T>& items) const {
        std::ofstream file(filepath);
        if (!file.is_open())
            throw std::runtime_error("Nu s-a putut scrie in fisierul: " + filepath);

        for (const auto& item : items)
            item.serialize(file);
    }
};
